:root{--pool:#b8e8f2;--ink:#123c86;--deep:#08285d;--paper:#fffefa;--lemon:#f9e779;--quiet:#35597b}
*{box-sizing:border-box}body{margin:0;background:var(--pool);color:var(--deep);font:17px/1.55 system-ui,sans-serif;scrollbar-color:var(--ink) var(--pool)}::selection{background:var(--lemon);color:var(--deep)}a{color:inherit;text-underline-offset:4px}button,a{touch-action:manipulation}button{font:600 16px/1.2 system-ui,sans-serif;min-height:48px;padding:12px 18px;border:1px solid var(--ink);border-radius:12px;color:var(--ink);background:var(--paper);cursor:pointer}button:hover{background:var(--lemon)}button:disabled{cursor:default;background:#e1edf1;color:#4b6275;border-color:#7995a7}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--deep);outline-offset:4px}main{max-width:1060px;margin:auto;padding:24px 32px 50px}nav{font-size:15px;display:flex;justify-content:space-between;gap:16px}h1,h2{font-family:Fredoka,system-ui,sans-serif;font-weight:600;line-height:1.02;letter-spacing:-.025em;text-wrap:balance}h1{font-size:clamp(44px,7.2vw,82px);margin:28px 0 12px;max-width:850px}h2{font-size:34px;margin:30px 0 12px}.intro{max-width:61ch;margin:0 0 24px}.art{width:100%;height:170px;object-fit:cover;object-position:center 52%;display:block;margin:20px 0 26px;border-radius:14px}.sheet{background:var(--paper);padding:24px;border-radius:16px;box-shadow:0 12px 32px #123c8618}.tabs{display:flex;gap:8px;margin-bottom:16px}.tabs button{flex:1;padding:12px 6px}.tabs button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}.tabs small{display:block;font-size:12px;margin-top:5px;font-weight:400}.pad{position:relative;background:#f4f9fb;border:1px solid #7798ba;border-radius:12px;overflow:hidden;aspect-ratio:12/5}canvas{display:block;width:100%;height:100%;touch-action:none}.pad span{position:absolute;bottom:8px;right:12px;color:var(--quiet);font-size:12px;pointer-events:none}.tools{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0 8px}.primary{background:var(--ink);color:white}.primary:hover{background:var(--deep);color:white}.status{min-height:1.6em;color:var(--quiet);font-size:15px;margin:8px 0 0}.ballot{margin-top:28px;padding-top:20px;border-top:1px solid #b9d1e1}.ballot p{margin:8px 0 16px}.votes{display:flex;flex-wrap:wrap;gap:10px}#reveal{margin-top:22px}#results{margin-top:30px}#resultTitle:focus{outline:none}.resultline{display:grid;grid-template-columns:90px 1fr;gap:16px;padding:18px 0;border-top:1px solid #91b6cc}.resultline strong{font-family:Fredoka,system-ui,sans-serif;font-size:25px}.resultline p{margin:0}.resultline canvas{height:64px;margin-top:10px;background:white;border:1px solid #91b6cc;border-radius:8px}.winner{background:var(--lemon);padding:16px;border-radius:12px}.fine{font-size:14px;color:var(--quiet)}details{margin-top:26px}summary{cursor:pointer;min-height:44px;padding:10px 0;font-weight:600}footer{margin-top:30px;max-width:70ch;font-size:14px}footer p{margin:10px 0} [hidden]{display:none!important}
