<nav><a href="./">Chloe Reads Jon</a><span>Trust your hand.</span></nav>
<h1>Blind Pen Derby</h1>
<p class="intro">Three mystery pens. One tiny test track. Try each, pick your favourite, then find out what your hand was voting for.</p>

<section class="sheet" aria-label="Blind pen trial">
<div class="tabs" aria-label="Choose a pen">
<button id="pen0" aria-pressed="true">Pen A<small>Not tried yet</small></button>
<button id="pen1" aria-pressed="false">Pen B<small>Not tried yet</small></button>
<button id="pen2" aria-pressed="false">Pen C<small>Not tried yet</small></button>
</div>
<div class="pad"><canvas id="pad" width="720" height="300" role="img" aria-label="Drawing pad. Trace the pale loop with a finger or mouse. For keyboard play, use Run a test stroke below."></canvas><span id="padLabel">Pen A · your sample</span></div>
<div class="tools"><button id="course" aria-pressed="false">Try the painted course</button><button id="demo" class="primary">Run a test stroke</button><button id="clear">Clear this sample</button></div>
<p class="status" id="status" role="status">Draw a few loops, or run a test stroke. Then switch pens.</p>
<div class="ballot"><strong>Your hand gets the deciding vote.</strong><p class="fine">Try all three before choosing. These are made-up digital pens, not simulations of real brands.</p>
<div class="votes"><button id="vote0" disabled>Choose A</button><button id="vote1" disabled>Choose B</button><button id="vote2" disabled>Choose C</button></div>
<button id="reveal" class="primary" disabled>Reveal the mystery pens</button></div>
</section>
<section id="results" hidden aria-labelledby="resultTitle"><h2 id="resultTitle" tabindex="-1">The labels come off.</h2><p id="verdict" class="winner"></p><div id="comparisons"></div><div class="tools"><button id="save" class="primary">Save the trial sheet</button><button id="again">Shuffle &amp; try again</button></div><p class="fine" id="saveStatus" role="status"></p></section>
<details><summary>Why the Mom Test?</summary><p>In 2009, Jon had read far too many pen reviews. His mum tried the pens and sorted them into the smooth ones and the ones she disliked. Her hands settled what the reviews couldn't.</p><p>This little derby borrows that idea, not her verdict. Compare three fictional ink behaviours without a price, a brand, or someone else's opinion getting in first.</p><p>The painted course is an original GPT Image illustration. Switch it on and follow the painted ink trails, or stay with the loop guide. Each round hides the behaviours in a fresh order. The test stroke follows exactly the same path for every pen. On a touchscreen, the page stays still while your finger is on the pad; scroll from outside it.</p></details>
<footer><p>Inspired by Jon's <a href="?source=1">In search of a decent pen: The Mom Test</a>.</p><p>Made for a little shared scribbling. Your samples stay in this tab. No scores, no accounts, no actual ink on the table.</p></footer>
</main><script>
'use strict';
const $=id=>document.getElementById(id), canvas=$('pad'),ctx=canvas.getContext('2d');
const letters=['A','B','C'];
const types=[
{name:'The Glider',desc:'A generous, continuous line that follows every turn directly. A broad ink trail makes little wobbles feel less fussy.',width:4.2,kind:'flow'},
{name:'The Skipper',desc:'A fine line with little dry gaps. The path follows your hand, but the ink occasionally takes a small holiday.',width:1.8,kind:'skip'},
{name:'The Wanderer',desc:'A fine line with a deliberately bumpy edge. Small sideways wiggles make the very same movement look scratchier.',width:1.8,kind:'rough'}
];
const courseArt=new Image();courseArt.src='data:image/webp;base64,';let painted=false;
let order=[],samples=[[],[],[]],selected=0,vote=null,revealed=false,active=false,current=null;
function shuffle(){order=[0,1,2];for(let i=2;i>0;i--){const a=new Uint32Array(1);crypto.getRandomValues(a);const limit=Math.floor(4294967296/(i+1))*(i+1);while(a[0]>=limit)crypto.getRandomValues(a);const j=a[0]%(i+1);[order[i],order[j]]=[order[j],order[i]];}}
function guide(c,w,h){c.save();c.strokeStyle='#6e8da8';c.lineWidth=1.4;c.setLineDash([5,7]);c.beginPath();for(let i=0;i<=240;i++){const x=50+i/240*620,y=150+Math.sin(i/240*Math.PI*6)*72;i?c.lineTo(x/720*w,y/300*h):c.moveTo(x/720*w,y/300*h);}c.stroke();c.restore();}
function ink(c,strokes,type,w=720,h=300){c.save();c.scale(w/720,h/300);c.strokeStyle='#123c86';c.lineWidth=type.width;c.lineCap='round';c.lineJoin='round';strokes.forEach(stroke=>{for(let i=1;i<stroke.length;i++){if(type.kind==='skip'&&Math.floor(i/6)%5===2)continue;let a=stroke[i-1],b=stroke[i];const off=n=>type.kind==='rough'?Math.sin(n*2.2)*2.8:0;c.beginPath();c.moveTo(a.x,a.y+off(i-1));c.lineTo(b.x,b.y+off(i));c.stroke();}});c.restore();}
function render(){ctx.clearRect(0,0,720,300);if(painted&&courseArt.complete){ctx.save();ctx.globalAlpha=.35;const scale=Math.min(720/courseArt.width,300/courseArt.height);ctx.drawImage(courseArt,(720-courseArt.width*scale)/2,(300-courseArt.height*scale)/2,courseArt.width*scale,courseArt.height*scale);ctx.restore();}else guide(ctx,720,300);ink(ctx,samples[selected],types[order[selected]]);$('padLabel').textContent='Pen '+letters[selected]+' · your sample';letters.forEach((l,i)=>{$('pen'+i).setAttribute('aria-pressed',String(i===selected));$('pen'+i).querySelector('small').textContent=samples[i].some(s=>s.length>3)?'Tried':'Not tried yet';});const ready=samples.every(a=>a.some(s=>s.length>3));letters.forEach((_,i)=>{$('vote'+i).disabled=!ready||revealed;$('vote'+i).setAttribute('aria-pressed',String(vote===i));$('vote'+i).style.background=vote===i?'var(--lemon)':'';});$('reveal').disabled=vote===null||revealed;}
function select(i){selected=i;active=false;current=null;render();$('status').textContent='Pen '+letters[i]+'. Draw here, or run the same test stroke.';}
function pos(e){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(720,(e.clientX-r.left)*720/r.width)),y:Math.max(0,Math.min(300,(e.clientY-r.top)*300/r.height))};}
canvas.addEventListener('pointerdown',e=>{if(revealed)return;e.preventDefault();active=true;canvas.setPointerCapture(e.pointerId);current=[pos(e)];samples[selected].push(current);});
canvas.addEventListener('pointermove',e=>{if(!active)return;current.push(pos(e));render();});
function end(){if(!active)return;active=false;current=null;render();$('status').textContent=samples.every(a=>a.some(s=>s.length>3))?'All three tried. Which one would you keep?':'Sample saved. Try another pen when you are ready.';}
canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);
letters.forEach((_,i)=>{$('pen'+i).onclick=()=>select(i);$('vote'+i).onclick=()=>{vote=i;render();$('status').textContent='Pen '+letters[i]+' is your pick. Ready for the reveal?';};});
$('course').onclick=()=>{painted=!painted;$('course').setAttribute('aria-pressed',String(painted));$('course').textContent=painted?'Return to loop course':'Try the painted course';render();$('status').textContent=painted?'Trace the original painted ink trails, or draw your own. Samples are kept.':'Back to the loop guide. Samples are kept.';};courseArt.onload=()=>render();
$('demo').onclick=()=>{const stroke=[];for(let i=0;i<=360;i++)stroke.push({x:50+i/360*620,y:150+Math.sin(i/360*Math.PI*6)*72});samples[selected]=[stroke];render();$('status').textContent=samples.every(a=>a.some(s=>s.length>3))?'All three tried. Choose your favourite below.':'Same path, different ink. Switch pens to compare.';};
$('clear').onclick=()=>{samples[selected]=[];vote=null;render();$('status').textContent='Pen '+letters[selected]+' cleared. Give it another go.';};
function comparisons(){const box=$('comparisons');box.replaceChildren();letters.forEach((l,i)=>{const row=document.createElement('div');row.className='resultline';const label=document.createElement('strong');label.textContent='Pen '+l;const text=document.createElement('div'),p=document.createElement('p');const b=document.createElement('b');b.textContent=types[order[i]].name+'. ';p.append(b,document.createTextNode(types[order[i]].desc));const c=document.createElement('canvas');c.width=720;c.height=100;c.setAttribute('role','img');c.setAttribute('aria-label','Your Pen '+l+' sample, revealed as '+types[order[i]].name);ink(c.getContext('2d'),samples[i],types[order[i]],720,100);text.append(p,c);row.append(label,text);box.append(row);});}
$('reveal').onclick=()=>{if(vote===null)return;revealed=true;render();$('demo').disabled=true;$('clear').disabled=true;comparisons();$('verdict').textContent='You chose Pen '+letters[vote]+': '+types[order[vote]].name+'. Your favourite is a preference, not a right answer.';$('results').hidden=false;$('status').textContent='Mystery solved. Your three samples are compared below.';$('resultTitle').focus();};
$('again').onclick=()=>{samples=[[],[],[]];selected=0;vote=null;revealed=false;shuffle();$('results').hidden=true;$('demo').disabled=false;$('clear').disabled=false;$('saveStatus').textContent='';render();$('status').textContent='Fresh order, clean paper. Try all three again.';$('pen0').focus();};
$('save').onclick=()=>{const c=document.createElement('canvas');c.width=1000;c.height=650;const x=c.getContext('2d');x.fillStyle='#b8e8f2';x.fillRect(0,0,1000,650);x.fillStyle='#08285d';x.font='bold 38px Fredoka, sans-serif';x.fillText('Blind Pen Derby',40,58);x.font='20px sans-serif';x.fillText('My pick: Pen '+letters[vote]+' · '+types[order[vote]].name,40,98);letters.forEach((l,i)=>{const y=130+i*150;x.fillStyle='#fffefa';x.fillRect(30,y,940,135);x.fillStyle='#08285d';x.font='bold 20px sans-serif';x.fillText('Pen '+l+' · '+types[order[i]].name,50,y+30);x.save();x.translate(50,y+38);ink(x,samples[i],types[order[i]],900,85);x.restore();});x.font='16px sans-serif';x.fillStyle='#08285d';x.fillText('Fictional digital pens. Inspired by Jon’s “The Mom Test” post.',40,620);c.toBlob(blob=>{if(!blob){$('saveStatus').textContent='Could not make the image. Please try again.';return;}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-blind-pen-derby.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);$('saveStatus').textContent='Trial sheet ready. Your browser may open it or offer a download.';});};
shuffle();render();
</script></body></html>
